import { useQuery } from '@tanstack/react-query';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import type { ContentfulClientApi } from 'contentful';
import { useContentfulClient } from './useContentfulClient';
import { filterByRegion, pickMostSpecificByRegion } from '../utils/resolveByRegion';
import { CONTENT_TYPE_IDS } from '../config/contentfulMapping';
import { CONTENTFUL_FALLBACK_LOCALE } from '../config/contentful';
import type { HeaderNavigationEntry, HeaderNavItemEntry } from '../types/contentful';

// Contentful resolves nested references `include` levels deep, and the header nav model is
// one level deeper than the footer's: headerNavigation → items (1) → columns (2) → links (3)
// → link.regions (4). See footer/index.tsx's FOOTER_INCLUDE_DEPTH comment for what getting
// this wrong looks like (an under-resolved `regions` reference arrives as an unresolvable
// link stub with no `fields`, which throws when read).
const HEADER_NAV_INCLUDE_DEPTH = 4;

const HEADER_NAV_QUERY_KEY = 'headerNavigation';

type UseHeaderNavResult = {
  /** Region-resolved header nav items for the current storefront. `undefined` only while the
   *  fetch is in flight — once settled (success, error, or no entry for this region) this is
   *  always an array, empty if there's nothing to show, so a consumer's loading indicator
   *  doesn't spin forever waiting for a value that will never arrive. */
  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
  isLoading: boolean;
  isError: boolean;
};

// useMultiSite ships untyped from the base SFCC package — same cast FooterContainer already
// uses for this exact lookup.
type MultiSiteResult = { site: { id: string }; locale?: { id: string } };

/**
 * Fetches the `headerNavigation` root entry from Contentful and resolves the region-scoped
 * entry for the current storefront, mirroring how `FooterContainer`
 * (overrides/app/components/footer/index.tsx) resolves `footerConfig` — same
 * `pickMostSpecificByRegion` root-resolution step, plus a `filterByRegion` pass over the
 * resolved entry's `items` array so each item's own `regions` field (per-item market
 * scoping, see headerNavItem.js) actually has an effect.
 *
 * Uses `@tanstack/react-query`'s `useQuery` rather than the footer's raw `useEffect`/
 * `useState` — the app already mounts a `QueryClientProvider` for every page via
 * `withReactQuery(AppConfig, ...)` in `_app-config`, so this needs no provider of its own.
 *
 * @returns the current storefront's resolved header nav items, plus query status flags.
 *   `items` is `undefined` while loading, on fetch failure, or when no entry resolves for
 *   this region — callers should treat that the same as "nothing to render yet," matching
 *   FooterContainer's "renders nothing" behaviour on an unresolved fetch.
 */
export const useHeaderNav = (): UseHeaderNavResult => {
  const { site, locale: siteLocale } = useMultiSite() as MultiSiteResult;
  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
  const { client } = useContentfulClient();

  const { data, isLoading, isError } = useQuery({
    queryKey: [HEADER_NAV_QUERY_KEY, site.id, locale],
    queryFn: async () => {
      // Guaranteed non-null: `enabled: !!client` below means this only runs once a client
      // exists, but TypeScript can't see that gate from inside the closure.
      // `useContentfulClient` types the client as `ContentfulClientApi<any>` for the
      // Experiences SDK's benefit — with `any` chain modifiers, `EntriesQueries`'s
      // `locale` field resolves out of the type entirely (see its `WITH_ALL_LOCALES`
      // conditional), so narrow back to the real default (`undefined`) modifiers here.
      const entries = await (client as ContentfulClientApi<undefined>)!.getEntries({
        content_type: CONTENT_TYPE_IDS.headerNavigation,
        include: HEADER_NAV_INCLUDE_DEPTH,
        locale,
      });
      // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
      // HeaderNavigationEntry mirrors the exact nested-resolved shape `include: 4`
      // produces for this content model.
      return entries.items as unknown as HeaderNavigationEntry[];
    },
    enabled: !!client,
  });

  const resolved = data ? pickMostSpecificByRegion<HeaderNavigationEntry>(data, site.id) : undefined;
  const items = isLoading
    ? undefined
    : resolved
    ? filterByRegion<HeaderNavItemEntry>(resolved.fields.items, site.id)
    : [];

  return { items, isLoading, isError };
};

