import React, { useEffect } from 'react';
import { Box, Center, Flex, Spinner, Stack, useTheme } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ListMenuPopover } from './list-menu-popover';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { MegaMenuContent } from 'app/components/list-menu/megaMenuContent';
import { useHeaderNav } from 'app/hooks/useHeaderNav';
import { useUiCopy } from 'app/hooks/useUiCopy';
import { useMegaMenuOpenReporter } from 'app/hooks/useMegaMenuOpenReporter';
import { useMegaMenuMotion } from 'app/hooks/useMegaMenuMotion';
import { useHeaderNavKeyboard } from 'app/hooks/useHeaderNavKeyboard';
import type { HeaderNavItemEntry } from 'app/types/contentful';

const MAXIMUM_NUMBER_COLUMNS = 5;

// headerNavItem's mega-menu columns live under `fields.columns`, not base SFCC's 'categories'
// default — ListMenuPopover/ListMenuContent index into `item[itemsKey]` generically.
const HEADER_NAV_ITEMS_KEY = 'columns';

type ListMenuViewProps = {
  /** Region-resolved header nav items, or undefined while loading (see useHeaderNav.ts). */
  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
  isLoading: boolean;
  maxColumns?: number;
};

/** Header desktop nav — presentational. Receives resolved `headerNavItem` entries as props and
 *  fetches nothing itself, matching the Footer/FooterContainer split — `ListMenu` below is this
 *  component's container.
 *
 * @param props see ListMenuViewProps
 */
export const ListMenuView = ({ items, isLoading, maxColumns = MAXIMUM_NUMBER_COLUMNS }: ListMenuViewProps) => {
  // components.ListMenu is dynamically registered and has no static type — cast unavoidable.
  const { components } = useTheme() as {
    components: Record<string, { baseStyle: Record<string, Record<string, unknown>> }>;
  };
  const { t } = useUiCopy();
  const { baseStyle } = components.ListMenu;

  // Single shared "which L1 item is open, and what motion phase it's in" source of truth — see
  // useMegaMenuMotion's own JSDoc for the open/switch/close choreography.
  const {
    activeItemId,
    pendingItemId,
    phase,
    hover,
    close,
    onExpandComplete,
    onContentInComplete,
    onContentOutComplete,
    onCollapseComplete,
  } = useMegaMenuMotion();

  // Reports the *list's* open/close state up to the header shell once here, rather than each
  // MegaMenuContent instance reporting its own isOpen — that used to race when switching
  // directly between items. `close` (not a raw state setter) is reported so RightBar's Close
  // control triggers the same fade-out-then-collapse sequence as any other close.
  const { reportOpen, reportClose } = useMegaMenuOpenReporter();
  useEffect(() => {
    if (activeItemId) {
      reportOpen(close);
    } else {
      reportClose();
    }
  }, [activeItemId, close, reportOpen, reportClose]);

  // The most recently *hovered* item — unlike activeItemId (which stays on the outgoing item
  // throughout a switch's fade-out), this changes instantly, so both L1 triggers' underlines
  // animate concurrently instead of the old one waiting for the switch to finish.
  const targetItemId = pendingItemId ?? activeItemId;

  // Left/Right/Home/End roving focus across the L1 triggers below — supplementary to native Tab
  // order, not a replacement for it. See useHeaderNavKeyboard.ts.
  const { getTriggerRef, onTriggerKeyDown } = useHeaderNavKeyboard();

  return (
    <nav id="list-menu" aria-label={t('list_menu.nav.assistive_msg', 'Main navigation')} aria-busy={isLoading}>
      {/* display="flex" overrides SFCC's display:{base:'none',lg:'flex'}; paddingLeft={0}
          removes SFCC's 4-unit offset (content padding lives in header.ts instead). */}
      <Flex {...baseStyle.container} display="flex" alignItems="center" paddingLeft={0}>
        {items ? (
          <Stack direction="row" {...baseStyle.stackContainer} gap="var(--zimm-scale-3xl)">
            {items.map((item, index) => {
              const { id } = item.sys;
              const { label, href, columns = [] } = item.fields;
              const itemsCount = columns.length;

              return (
                <Box key={id}>
                  {itemsCount > 0 ? (
                    <ListMenuPopover
                      key={id}
                      maxColumns={maxColumns}
                      item={item}
                      name={label}
                      itemsKey={HEADER_NAV_ITEMS_KEY}
                      contentComponent={MegaMenuContent}
                      // True for both the outgoing and incoming item during a switch — lets the
                      // incoming item's Popover pre-position before it visually takes over (see
                      // list-menu-popover.tsx's isActiveItem doc comment).
                      isOpen={activeItemId === id || pendingItemId === id}
                      isActiveItem={activeItemId === id}
                      isTriggerActive={targetItemId === id}
                      motionPhase={phase}
                      onOpen={() => hover(id)}
                      onClose={close}
                      onExpandComplete={onExpandComplete}
                      onContentInComplete={onContentInComplete}
                      onContentOutComplete={onContentOutComplete}
                      onCollapseComplete={onCollapseComplete}
                      triggerRef={getTriggerRef(index)}
                      onTriggerKeyDown={onTriggerKeyDown(index)}
                    />
                  ) : (
                    <ZimmNavItem
                      label={label}
                      href={href}
                      growUnderline
                      ref={getTriggerRef(index)}
                      onKeyDown={onTriggerKeyDown(index)}
                    />
                  )}
                </Box>
              );
            })}
          </Stack>
        ) : (
          // Scoped to just this loading indicator, not the whole nav (see the removed
          // aria-live/aria-atomic above) — Chakra's Spinner carries its own visually-hidden
          // "Loading..." label, so this announces once, atomically, when it appears. Wrapping
          // the *entire* nav in aria-live+aria-atomic instead (the previous shape of this code)
          // re-announced this whole subtree — every mega-menu link, plus the promo image's alt
          // text — on every later, unrelated mutation inside it (e.g. a mega menu's own opening
          // animation updating an inline style), which is what produced the "screen reader reads
          // everything at once" bug. A live region that large has no natural target text and no
          // matching mutation to react to that a shopper would actually want announced.
          <Center p="2" aria-live="polite" aria-atomic="true">
            <Spinner size="lg" />
          </Center>
        )}
      </Flex>
    </nav>
  );
};

ListMenuView.displayName = 'ListMenuView';

type ListMenuProps = {
  /** Accepted only for call-site compatibility with base `_app.jsx`'s SFCC category-tree
   *  contract. `ListMenu` self-fetches its own data via `useHeaderNav()`, so all of these are
   *  ignored except `maxColumns`. */
  root?: Record<string, unknown>;
  contentComponent?: React.ElementType;
  itemsKey?: string;
  itemsCountKey?: string;
  maxColumns?: number;
};

/** Header desktop nav — container. Fetches `headerNavItem` entries via `useHeaderNav()` and
 *  renders `ListMenuView` with the result.
 *
 * @param props see ListMenuProps
 */
const ListMenu = ({ maxColumns }: ListMenuProps) => {
  const { items, isLoading } = useHeaderNav();

  return <ListMenuView items={items} isLoading={isLoading} maxColumns={maxColumns} />;
};

ListMenu.displayName = 'ListMenu';

export { ListMenu };

