#!/usr/bin/env node
/**
 * Populate .env with Contentful API tokens fetched live from the space.
 *
 * Rules:
 *   - Missing var  → added at the end of the Contentful block
 *   - Empty var    → filled with the live value
 *   - Wrong var    → updated with the live value
 *   - CONTENTFUL_MANAGEMENT_TOKEN → never touched (per-user personal token)
 *
 * Write access (add/update) is gated to @ZimmermannAU/tier-1-approvers.
 * Non-approvers get a read-only view of what the values should be.
 *
 * Usage:
 *   npm run config:contentful               # update .env if authorised
 *   npm run config:contentful -- --dry-run  # print changes without writing
 */

import { readFileSync, writeFileSync, existsSync } from 'fs';
import { execSync } from 'child_process';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { checkEnv, createClient, log } from './_shared.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '../../../');
const ENV_FILE = resolve(REPO_ROOT, '.env');
const DRY_RUN = process.argv.includes('--dry-run');

const ENVIRONMENT_IDS = ['master', 'dev', 'test', 'sit', 'staging', 'uat'];
const SKIP_VARS = new Set(['CONTENTFUL_MANAGEMENT_TOKEN']);

// Vars managed by this script, keyed by their .env name
const MANAGED_VARS = [
  'CONTENTFUL_SPACE_ID',
  'CONTENTFUL_ENVIRONMENT_ID',
  'CONTENTFUL_DELIVERY_TOKEN',
  'CONTENTFUL_PREVIEW_TOKEN',
];

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

// ── Tier 1 gate ──────────────────────────────────────────────────────────────

async function isTier1Approver() {
  try {
    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    const membersRaw = execSync(
      "gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'",
      { encoding: 'utf8' },
    ).trim();
    const members = membersRaw.split('\n').filter(Boolean);
    return { approved: members.includes(login), login };
  } catch {
    return { approved: false, login: 'unknown' };
  }
}

// ── .env parsing ─────────────────────────────────────────────────────────────

function parseEnv(content) {
  return content.split('\n').map((line) => {
    if (line.startsWith('#') || line.trim() === '') {
      return { type: 'raw', value: line };
    }
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) return { type: 'raw', value: line };
    return { type: 'var', key: line.slice(0, eqIdx), value: line.slice(eqIdx + 1) };
  });
}

function serializeEnv(entries) {
  return entries.map((e) => (e.type === 'var' ? `${e.key}=${e.value}` : e.value)).join('\n');
}

// ── Main ─────────────────────────────────────────────────────────────────────

async function main() {
  const { approved, login } = await isTier1Approver();

  if (!approved) {
    log.warn(`Authenticated as '${login}' — not a tier-1-approver. Running in read-only mode.`);
  } else {
    log.info(`Authenticated as '${login}' (tier-1-approver). Write access granted.`);
  }

  const canWrite = approved && !DRY_RUN;
  if (DRY_RUN) log.info('Dry-run flag set — no writes will occur.');

  // Fetch live config from Contentful
  const client = createClient();
  const spaceId = process.env.CONTENTFUL_SPACE_ID;

  log.section('Fetching live API keys from Contentful');
  const { items: apiKeys } = await client.apiKey.getMany({ query: { limit: 100 } });

  // Build a map: environmentId → { deliveryToken, previewToken }
  const tokenMap = {};
  for (const key of apiKeys) {
    const envLink = key.environments?.[0];
    if (!envLink) continue;
    const envId = envLink.sys.id;

    // Fetch the linked preview key
    let previewToken = '';
    if (key.preview_api_key?.sys?.id) {
      try {
        const previewKey = await client.previewApiKey.get({
          previewApiKeyId: key.preview_api_key.sys.id,
        });
        previewToken = previewKey.accessToken;
      } catch {
        // non-fatal — preview key may not exist yet
      }
    }

    tokenMap[envId] = { deliveryToken: key.accessToken, previewToken };
  }

  // .env update logic
  if (!existsSync(ENV_FILE)) {
    log.error('.env file not found at repo root. Create it from .env.sample first.');
    process.exit(1);
  }

  const raw = readFileSync(ENV_FILE, 'utf8');
  const entries = parseEnv(raw);
  const changes = [];

  function upsertVar(key, value) {
    if (SKIP_VARS.has(key)) return;
    const existing = entries.find((e) => e.type === 'var' && e.key === key);
    if (!existing) {
      entries.push({ type: 'var', key, value });
      changes.push({ action: 'add', key, value });
    } else if (!existing.value) {
      existing.value = value;
      changes.push({ action: 'fill', key, value });
    } else if (existing.value !== value) {
      existing.value = value;
      changes.push({ action: 'update', key, value });
    }
  }

  // Always ensure CONTENTFUL_SPACE_ID is correct
  upsertVar('CONTENTFUL_SPACE_ID', spaceId);

  // Populate tokens for the local dev environment
  const localEnvId = process.env.CONTENTFUL_ENVIRONMENT_ID || 'dev';
  const localTokens = tokenMap[localEnvId];
  if (localTokens) {
    upsertVar('CONTENTFUL_DELIVERY_TOKEN', localTokens.deliveryToken);
    upsertVar('CONTENTFUL_PREVIEW_TOKEN', localTokens.previewToken);
  } else {
    log.warn(`No API key found for environment '${localEnvId}'. Run setup:contentful first.`);
  }

  // Print the full token map for all environments (always shown, regardless of write access)
  log.section('Live token values per environment');
  for (const envId of ENVIRONMENT_IDS) {
    const tokens = tokenMap[envId];
    if (!tokens) {
      log.warn(`${envId}: no API key found (run setup:contentful)`);
    } else {
      console.log(`  ${envId.padEnd(10)} delivery: ${tokens.deliveryToken.slice(0, 8)}…  preview: ${tokens.previewToken ? tokens.previewToken.slice(0, 8) + '…' : '(none)'}`);
    }
  }

  if (changes.length === 0) {
    log.success('.env is already up to date.');
    return;
  }

  log.section('Changes');
  for (const c of changes) {
    const label = c.action === 'add' ? '+ add  ' : c.action === 'fill' ? '~ fill ' : '~ update';
    console.log(`  ${label}  ${c.key}`);
  }

  if (!canWrite) {
    log.warn(approved ? 'Dry-run — no writes made.' : 'Read-only — contact a tier-1-approver to apply these changes.');
    return;
  }

  writeFileSync(ENV_FILE, serializeEnv(entries), 'utf8');
  log.success(`.env updated (${changes.length} change${changes.length === 1 ? '' : 's'}).`);
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

