import { createClient } from 'contentful-management';
import { readFileSync } from 'fs';

function loadEnv(path) {
  const raw = readFileSync(path, 'utf8');
  for (const line of raw.split('\n')) {
    if (!line || line.startsWith('#')) continue;
    const idx = line.indexOf('=');
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim();
    if (key && !(key in process.env)) process.env[key] = value;
  }
}
loadEnv(new URL('./.env', import.meta.url));

const spaceId = process.env.CONTENTFUL_SPACE_ID;
const environmentId = process.env.CONTENTFUL_ENVIRONMENT_ID || 'dev';

const client = createClient(
  { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
  { type: 'plain', defaults: { spaceId, environmentId } },
);

const NAV_TYPES = ['headerNavigation', 'headerNavItem', 'navGroup', 'link', 'region', 'image'];

function fmtUser(u) {
  if (!u) return '(none)';
  if (u.sys?.type && u.sys.type !== 'User') return `[${u.sys.type}:${u.sys.id?.slice(0, 10)}]`;
  const name = [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || u.sys?.id;
  return `${name} (User:${u.sys?.id?.slice(0, 10)})`;
}

async function main() {
  console.log(`Space ${spaceId} / environment ${environmentId}\n`);

  const userCache = new Map();
  async function resolveUser(link) {
    if (!link) return null;
    const id = link.sys.id;
    if (link.sys.linkType !== 'User') return { sys: { type: link.sys.linkType, id } };
    if (userCache.has(id)) return userCache.get(id);
    try {
      const u = await client.user.get({ userId: id });
      userCache.set(id, u);
      return u;
    } catch (e) {
      console.error(`      [user.get(${id}) failed: ${e.status ?? ''} ${e.message}]`);
      return { sys: { type: 'User(unresolved)', id } };
    }
  }

  for (const type of NAV_TYPES) {
    let entries;
    try {
      entries = await client.entry.getMany({ query: { content_type: type, limit: 100 } });
    } catch (e) {
      console.log(`## ${type}: ERROR ${e.message}\n`);
      continue;
    }
    console.log(`## ${type}: ${entries.total} entr${entries.total === 1 ? 'y' : 'ies'}`);
    for (const e of entries.items) {
      const createdBy = await resolveUser(e.sys.createdBy);
      const updatedBy = await resolveUser(e.sys.updatedBy);
      const fields = e.fields || {};
      const localeKey =
        Object.keys(fields.label || fields.internalTitle || fields.href || fields.siteId || {})[0] || '??';
      const label = fields.label?.[localeKey] ?? fields.internalTitle?.[localeKey] ?? '';
      const href = fields.href?.[localeKey];
      const siteId = fields.siteId?.[localeKey];
      console.log(
        `  - ${e.sys.id.slice(0, 10)} "${label}"${href !== undefined ? ` href="${href}"` : ''}${
          siteId !== undefined ? ` siteId="${siteId}"` : ''
        } v${e.sys.version}\n` +
          `      created ${e.sys.createdAt} by ${fmtUser(createdBy)}` +
          (e.sys.updatedAt !== e.sys.createdAt ? `\n      updated ${e.sys.updatedAt} by ${fmtUser(updatedBy)}` : ''),
      );
    }
    console.log('');
  }

  console.log('## Installed apps (this environment)');
  try {
    const apps = await client.appInstallation.getMany({});
    if (apps.items.length === 0) console.log('  (none installed)\n');
    for (const a of apps.items) {
      console.log(`  - ${a.sys.appDefinition.sys.id}`);
    }
  } catch (e) {
    console.log(`  ERROR: ${e.message}\n`);
  }

  console.log('\n## Live content-type fields (nav-related, straight from the API)');
  for (const type of ['headerNavItem', 'navGroup', 'link', 'headerNavigation']) {
    try {
      const ct = await client.contentType.get({ contentTypeId: type });
      console.log(`  - ${type}: ${ct.fields.map((f) => `${f.id}:${f.type}`).join(', ')}`);
    } catch (e) {
      console.log(`  - ${type}: ERROR ${e.message}`);
    }
  }

  console.log('\n## Webhooks (space-level, all environments)');
  try {
    const hooks = await client.webhook.getMany({});
    if (hooks.items.length === 0) console.log('  (none configured)');
    for (const h of hooks.items) {
      console.log(`  - "${h.name}" -> ${h.url}`);
    }
  } catch (e) {
    console.log(`  ERROR: ${e.message}`);
  }
}

main().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});
